[
  {
    "version": "v0.9",
    "type": "createSurface",
    "surfaceId": "rome-itinerary-surface",
    "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json",
    "title": "Rome 2-Day Walking Itinerary"
  },
  {
    "version": "v0.9",
    "type": "updateComponents",
    "surfaceId": "rome-itinerary-surface",
    "components": [
      {
        "id": "root",
        "type": "Column",
        "properties": {
          "children": [
            {
              "id": "title_text",
              "type": "Text",
              "properties": {
                "text": "Rome 2-Day Walking Itinerary: Pantheon Base",
                "style": "title"
              }
            },
            {
              "id": "main_tabs",
              "type": "Tabs",
              "properties": {
                "tabs": [
                  {
                    "id": "overview_tab",
                    "type": "Tab",
                    "properties": {
                      "label": "Overview",
                      "child": "overview_content"
                    }
                  },
                  {
                    "id": "day1_tab",
                    "type": "Tab",
                    "properties": {
                      "label": "Day 1: Ancient Rome",
                      "child": "day1_content"
                    }
                  },
                  {
                    "id": "day2_tab",
                    "type": "Tab",
                    "properties": {
                      "label": "Day 2: Vatican & Wonders",
                      "child": "day2_content"
                    }
                  }
                ]
              }
            }
          ]
        }
      },
      {
        "id": "overview_content",
        "type": "Column",
        "properties": {
          "spacing": "medium",
          "children": [
            {
              "id": "assumptions_heading",
              "type": "Text",
              "properties": {
                "text": "Assumptions",
                "style": "heading"
              }
            },
            {
              "id": "assumptions_list",
              "type": "List",
              "properties": {
                "children": [
                  {
                    "id": "assumption_1",
                    "type": "ListItem",
                    "properties": {
                      "primaryText": "Moderate fitness level (15,000-25,000 steps per day)."
                    }
                  },
                  {
                    "id": "assumption_2",
                    "type": "ListItem",
                    "properties": {
                      "primaryText": "All major attraction tickets will be pre-booked online."
                    }
                  },
                  {
                    "id": "assumption_3",
                    "type": "ListItem",
                    "properties": {
                      "primaryText": "Budget of €100/person/day is for food and entry fees only."
                    }
                  },
                  {
                    "id": "assumption_4",
                    "type": "ListItem",
                    "properties": {
                      "primaryText": "Prices are estimates for 2024 and should be verified."
                    }
                  }
                ]
              }
            },
            {
              "id": "checklist_heading",
              "type": "Text",
              "properties": {
                "text": "Pre-Trip Checklist",
                "style": "heading"
              }
            },
            {
              "id": "checklist_list",
              "type": "List",
              "properties": {
                "children": [
                  {
                    "id": "checklist_1",
                    "type": "ListItem",
                    "properties": {
                      "primaryText": "Book Colosseum & Roman Forum ticket online for Day 1 (9:00 AM slot)."
                    }
                  },
                  {
                    "id": "checklist_2",
                    "type": "ListItem",
                    "properties": {
                      "primaryText": "Book Vatican Museums & Sistine Chapel ticket online for Day 2 (8:30 AM slot)."
                    }
                  },
                  {
                    "id": "checklist_3",
                    "type": "ListItem",
                    "properties": {
                      "primaryText": "Purchase the new Pantheon entry ticket online or plan to queue."
                    }
                  },
                  {
                    "id": "checklist_4",
                    "type": "ListItem",
                    "properties": {
                      "primaryText": "Download an offline map of Rome."
                    }
                  },
                  {
                    "id": "checklist_5",
                    "type": "ListItem",
                    "properties": {
                      "primaryText": "Pack comfortable walking shoes. This is the most important item."
                    }
                  }
                ]
              }
            },
            {
              "id": "budget_heading",
              "type": "Text",
              "properties": {
                "text": "Budget & Ticket Framework (€100/day)",
                "style": "heading"
              }
            },
            {
              "id": "budget_table_list",
              "type": "List",
              "properties": {
                "children": [
                  {
                    "id": "budget_header",
                    "type": "ListItem",
                    "properties": {
                      "primaryText": "**Category**",
                      "secondaryText": "**Estimated Cost** | Notes"
                    }
                  },
                  {
                    "id": "budget_divider_1",
                    "type": "Divider"
                  },
                  {
                    "id": "budget_item_1",
                    "type": "ListItem",
                    "properties": {
                      "primaryText": "Entry Fees (Avg.)",
                      "secondaryText": "**€25** | Colosseum (~€20), Vatican (~€25), Pantheon (€5). Averaged over 2 days."
                    }
                  },
                  {
                    "id": "budget_item_2",
                    "type": "ListItem",
                    "properties": {
                      "primaryText": "Breakfast",
                      "secondaryText": "**€5** | Cappuccino and a cornetto at a local bar."
                    }
                  },
                  {
                    "id": "budget_item_3",
                    "type": "ListItem",
                    "properties": {
                      "primaryText": "Lunch",
                      "secondaryText": "**€15** | Pizza al taglio (by the slice) or a fresh panino."
                    }
                  },
                  {
                    "id": "budget_item_4",
                    "type": "ListItem",
                    "properties": {
                      "primaryText": "Dinner",
                      "secondaryText": "**€40** | Sit-down meal at a trattoria (pasta/pizza, wine, water)."
                    }
                  },
                  {
                    "id": "budget_item_5",
                    "type": "ListItem",
                    "properties": {
                      "primaryText": "Snacks/Gelato",
                      "secondaryText": "**€15** | Includes water, coffee breaks, and essential daily gelato."
                    }
                  },
                  {
                    "id": "budget_divider_2",
                    "type": "Divider"
                  },
                  {
                    "id": "budget_total",
                    "type": "ListItem",
                    "properties": {
                      "primaryText": "**Total**",
                      "secondaryText": "**€100**"
                    }
                  }
                ]
              }
            },
            {
              "id": "quick_actions_heading",
              "type": "Text",
              "properties": {
                "text": "Quick Actions",
                "style": "subheading"
              }
            },
            {
              "id": "quick_actions_row",
              "type": "Row",
              "properties": {
                "spacing": "medium",
                "children": [
                  {
                    "id": "book_colosseum_btn",
                    "type": "Button",
                    "properties": {
                      "label": "Book Colosseum Tickets",
                      "action": {
                        "type": "functionCall",
                        "call": "openUrl",
                        "args": {
                          "url": "https://www.coopculture.it/en/products/ticket-colosseum-roman-forum-palatine_24h/"
                        }
                      }
                    }
                  },
                  {
                    "id": "book_vatican_btn",
                    "type": "Button",
                    "properties": {
                      "label": "Book Vatican Museums Tickets",
                      "action": {
                        "type": "functionCall",
                        "call": "openUrl",
                        "args": {
                          "url": "https://tickets.museivaticani.va/home"
                        }
                      }
                    }
                  }
                ]
              }
            },
            {
              "id": "sources_heading",
              "type": "Text",
              "properties": {
                "text": "Sources",
                "style": "subheading"
              }
            },
            {
              "id": "sources_text",
              "type": "Text",
              "properties": {
                "text": "- [Official Colosseum Ticket Vendor](https://www.coopculture.it/en/products/ticket-colosseum-roman-forum-palatine_24h/)\n- [Official Vatican Museums Tickets](https://tickets.museivaticani.va/home)\n- [Official Pantheon Information](https://www.pantheonroma.com/home/)"
              }
            }
          ]
        }
      },
      {
        "id": "day1_content",
        "type": "Column",
        "properties": {
          "spacing": "medium",
          "children": [
            {
              "id": "day1_image",
              "type": "Image",
              "properties": {
                "path": "/colosseum",
                "alt": "The Colosseum in Rome"
              }
            },
            {
              "id": "day1_focus",
              "type": "Text",
              "properties": {
                "text": "**Focus:** Immerse yourself in the heart of the Roman Empire.",
                "style": "body"
              }
            },
            {
              "id": "day1_morning_heading",
              "type": "Text",
              "properties": {
                "text": "Morning (8:00 AM - 1:00 PM)",
                "style": "heading"
              }
            },
            {
              "id": "day1_event_1",
              "type": "Row",
              "properties": {
                "children": [
                  {
                    "id": "day1_icon_1",
                    "type": "Icon",
                    "properties": {
                      "name": "/sightseeing"
                    }
                  },
                  {
                    "id": "day1_text_1",
                    "type": "Text",
                    "properties": {
                      "text": "**8:00 AM:** Start from Pantheon, walk to Piazza Venezia to see Altare della Patria (Vittoriano) from the outside."
                    }
                  }
                ]
              }
            },
            {
              "id": "day1_event_2",
              "type": "Row",
              "properties": {
                "children": [
                  {
                    "id": "day1_icon_2",
                    "type": "Icon",
                    "properties": {
                      "name": "/walking"
                    }
                  },
                  {
                    "id": "day1_text_2",
                    "type": "Text",
                    "properties": {
                      "text": "Pantheon to Piazza Venezia: Approx. 10 minutes."
                    }
                  }
                ]
              }
            },
            {
              "id": "day1_event_3",
              "type": "Row",
              "properties": {
                "children": [
                  {
                    "id": "day1_icon_3",
                    "type": "Icon",
                    "properties": {
                      "name": "/sightseeing"
                    }
                  },
                  {
                    "id": "day1_text_3",
                    "type": "Text",
                    "properties": {
                      "text": "**8:30 AM:** Walk along Via dei Fori Imperiali towards the Colosseum."
                    }
                  }
                ]
              }
            },
            {
              "id": "day1_event_4",
              "type": "Row",
              "properties": {
                "children": [
                  {
                    "id": "day1_icon_4",
                    "type": "Icon",
                    "properties": {
                      "name": "/sightseeing"
                    }
                  },
                  {
                    "id": "day1_text_4",
                    "type": "Text",
                    "properties": {
                      "text": "**9:00 AM - 12:00 PM: Colosseum, Roman Forum & Palatine Hill.** Use your pre-booked 9:00 AM ticket. Allow ~3 hours for all three sites."
                    }
                  }
                ]
              }
            },
            {
              "id": "day1_event_5",
              "type": "Row",
              "properties": {
                "children": [
                  {
                    "id": "day1_icon_5",
                    "type": "Icon",
                    "properties": {
                      "name": "/tip"
                    }
                  },
                  {
                    "id": "day1_text_5",
                    "type": "Text",
                    "properties": {
                      "text": "After the Colosseum, start with Palatine Hill for great views over the Forum."
                    }
                  }
                ]
              }
            },
            {
              "id": "day1_lunch_heading",
              "type": "Text",
              "properties": {
                "text": "Lunch (1:00 PM - 2:00 PM)",
                "style": "heading"
              }
            },
            {
              "id": "day1_lunch_text",
              "type": "Row",
              "properties": {
                "children": [
                  {
                    "id": "day1_icon_6",
                    "type": "Icon",
                    "properties": {
                      "name": "/food"
                    }
                  },
                  {
                    "id": "day1_text_6",
                    "type": "Text",
                    "properties": {
                      "text": "Avoid restaurants directly facing the Colosseum. Walk towards the Monti or Celio neighborhoods for better value."
                    }
                  }
                ]
              }
            },
            {
              "id": "day1_lunch_cards",
              "type": "Row",
              "properties": {
                "spacing": "medium",
                "children": [
                  {
                    "id": "day1_lunch_card_1",
                    "type": "Card",
                    "properties": {
                      "title": "Pizza al Taglio",
                      "subtitle": "Forno da Milvio | €10-€15",
                      "body": "Grab delicious, affordable pizza by the slice."
                    }
                  },
                  {
                    "id": "day1_lunch_card_2",
                    "type": "Card",
                    "properties": {
                      "title": "Quick Panini",
                      "subtitle": "La Prezzemolina | €8-€12",
                      "body": "Fresh, made-to-order sandwiches for a fast and tasty lunch."
                    }
                  },
                  {
                    "id": "day1_lunch_card_3",
                    "type": "Card",
                    "properties": {
                      "title": "Local Trattoria",
                      "subtitle": "Hostaria I Clementini | €20-€25",
                      "body": "A short walk away for authentic Roman pasta if you want a sit-down meal."
                    }
                  }
                ]
              }
            },
            {
              "id": "day1_afternoon_heading",
              "type": "Text",
              "properties": {
                "text": "Afternoon (2:00 PM - 6:00 PM)",
                "style": "heading"
              }
            },
            {
              "id": "day1_event_6",
              "type": "Row",
              "properties": {
                "children": [
                  {
                    "id": "day1_icon_7",
                    "type": "Icon",
                    "properties": {
                      "name": "/walking"
                    }
                  },
                  {
                    "id": "day1_text_7",
                    "type": "Text",
                    "properties": {
                      "text": "**2:00 PM:** Stroll past Circus Maximus and the optional Mouth of Truth (expect a queue)."
                    }
                  }
                ]
              }
            },
            {
              "id": "day1_event_7",
              "type": "Row",
              "properties": {
                "children": [
                  {
                    "id": "day1_icon_8",
                    "type": "Icon",
                    "properties": {
                      "name": "/sightseeing"
                    }
                  },
                  {
                    "id": "day1_text_8",
                    "type": "Text",
                    "properties": {
                      "text": "**4:00 PM:** Climb Capitoline Hill."
                    }
                  }
                ]
              }
            },
            {
              "id": "day1_event_8",
              "type": "Row",
              "properties": {
                "children": [
                  {
                    "id": "day1_icon_9",
                    "type": "Icon",
                    "properties": {
                      "name": "/tip"
                    }
                  },
                  {
                    "id": "day1_text_9",
                    "type": "Text",
                    "properties": {
                      "text": "Don't miss the free, spectacular panoramic view over the Roman Forum from the back of Piazza del Campidoglio."
                    }
                  }
                ]
              }
            },
            {
              "id": "day1_evening_heading",
              "type": "Text",
              "properties": {
                "text": "Evening (6:00 PM onwards)",
                "style": "heading"
              }
            },
            {
              "id": "day1_event_9",
              "type": "Row",
              "properties": {
                "children": [
                  {
                    "id": "day1_icon_10",
                    "type": "Icon",
                    "properties": {
                      "name": "/food"
                    }
                  },
                  {
                    "id": "day1_text_10",
                    "type": "Text",
                    "properties": {
                      "text": "**7:30 PM:** Dinner in the Jewish Ghetto or near Campo de' Fiori."
                    }
                  }
                ]
              }
            },
            {
              "id": "day1_dinner_cards",
              "type": "Row",
              "properties": {
                "spacing": "medium",
                "children": [
                  {
                    "id": "day1_dinner_card_1",
                    "type": "Card",
                    "properties": {
                      "title": "Roman-Jewish",
                      "subtitle": "Nonna Betta | €35-€45",
                      "body": "Famous for artichokes 'alla giudia' in the heart of the Jewish Ghetto."
                    }
                  },
                  {
                    "id": "day1_dinner_card_2",
                    "type": "Card",
                    "properties": {
                      "title": "Classic Pasta",
                      "subtitle": "Osteria da Fortunata | €30-€40",
                      "body": "Near Campo de' Fiori, watch pasta being handmade in the window."
                    }
                  },
                  {
                    "id": "day1_dinner_card_3",
                    "type": "Card",
                    "properties": {
                      "title": "Budget Pizza",
                      "subtitle": "Emma Pizzeria | €25-€35",
                      "body": "Excellent thin-crust Roman pizza in a stylish setting."
                    }
                  }
                ]
              }
            },
            {
              "id": "day1_event_10",
              "type": "Row",
              "properties": {
                "children": [
                  {
                    "id": "day1_icon_1
